from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for optimized matrix multiplication with register blocking
matrix_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 16  // Threads per dimension (16x16 = 256 threads)

__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes 2x2 elements
    constexpr int REG_TILE_X = 2;
    constexpr int REG_TILE_Y = 2;

    // Starting position of the tile
    int row_start = by * TILE_SIZE + ty * REG_TILE_Y;
    int col_start = bx * TILE_SIZE + tx * REG_TILE_X;

    // Register accumulators
    float c[REG_TILE_Y][REG_TILE_X] = {{0}};

    // Loop over tiles
    for (int k = 0; k < N; k += TILE_SIZE) {
        // Prefetch tile from A into shared memory
        #pragma unroll
        for (int y = 0; y < REG_TILE_Y; y++) {
            int row = row_start + y;
            if (row < N && (k + tx) < N) {
                As[ty * REG_TILE_Y + y][tx] = A[row * N + k + tx];
            } else {
                As[ty * REG_TILE_Y + y][tx] = 0.0f;
            }
        }

        // Prefetch tile from B into shared memory
        #pragma unroll
        for (int x = 0; x < REG_TILE_X; x++) {
            int col = col_start + x;
            if ((k + ty) < N && col < N) {
                Bs[ty][tx * REG_TILE_X + x] = B[(k + ty) * N + col];
            } else {
                Bs[ty][tx * REG_TILE_X + x] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial dot products
        #pragma unroll
        for (int kk = 0; kk < TILE_SIZE; kk++) {
            #pragma unroll
            for (int y = 0; y < REG_TILE_Y; y++) {
                float a_val = As[ty * REG_TILE_Y + y][kk];
                #pragma unroll
                for (int x = 0; x < REG_TILE_X; x++) {
                    c[y][x] += a_val * Bs[kk][tx * REG_TILE_X + x];
                }
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    #pragma unroll
    for (int y = 0; y < REG_TILE_Y; y++) {
        int row = row_start + y;
        #pragma unroll
        for (int x = 0; x < REG_TILE_X; x++) {
            int col = col_start + x;
            if (row < N && col < N) {
                C[row * N + col] = c[y][x];
            }
        }
    }
}

